// Run settings for one curation run: which month, the rules from the environment, the dates
// that decide which batches can go in a box, and the Airtable formulas for the reads.
function readSettings(trigger, env, askedMonth, now, executionId) {
  const problems = [];
  for (const name of ['AIRTABLE_TOKEN', 'AIRTABLE_BASE_ID', 'SLACK_PACKING_WEBHOOK_URL']) {
    if (!String(env[name] == null ? '' : env[name]).trim()) problems.push(`${name} is not set`);
  }
  const whole = (name, fallback, min, max) => {
    const raw = String(env[name] == null ? '' : env[name]).trim();
    if (raw === '') return fallback;
    if (!/^\d+$/.test(raw) || Number(raw) < min || Number(raw) > max) {
      problems.push(`${name} must be a whole number from ${min} to ${max}`);
      return fallback;
    }
    return Number(raw);
  };
  const repeatWindow = whole('REPEAT_WINDOW', 1, 0, 12);
  const sellByBufferDays = whole('SELL_BY_BUFFER_DAYS', 14, 0, 365);

  const pad = n => String(n).padStart(2, '0');
  const shift = (ym, by) => {
    const [y, m] = ym.split('-').map(Number);
    const total = y * 12 + (m - 1) + by;
    return `${Math.floor(total / 12)}-${pad((total % 12) + 1)}`;
  };
  const today = now.toISOString().slice(0, 10);
  const thisMonth = today.slice(0, 7);
  const nextMonth = shift(thisMonth, 1);
  let month = nextMonth;
  let requestError = '';
  const asked = askedMonth == null ? '' : String(askedMonth).trim();
  if (asked) {
    if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(asked)) requestError = `month "${asked.slice(0, 20)}" is not in the form YYYY-MM, for example ${nextMonth}`;
    else if (asked !== thisMonth && asked !== nextMonth) requestError = `month ${asked} cannot be curated now. Use this month (${thisMonth}) or next month (${nextMonth}), in UTC`;
    else month = asked;
  }

  // Boxes ship from the first day of the month (or today, when curating the current month).
  // A bar must still have more than SELL_BY_BUFFER_DAYS days to its best before date then.
  const monthStart = `${month}-01`;
  const shipDate = today > monthStart ? today : monthStart;
  const cutoff = new Date(shipDate + 'T00:00:00Z');
  cutoff.setUTCDate(cutoff.getUTCDate() + sellByBufferDays);
  const shelfLifeCutoff = cutoff.toISOString().slice(0, 10);

  // Box History and Box Shipments are read for this month and the 12 before it.
  const lookbackMonths = Array.from({ length: 13 }, (_, i) => shift(month, -i));
  const monthFormula = 'OR(' + lookbackMonths.map(m => `{Box Month} = '${m}'`).join(', ') + ')';
  const startedAt = now.toISOString().replace(/\.\d{3}Z$/, 'Z');
  // The n8n execution id makes the Run ID unique, also for two runs started in the same second.
  const runId = `boxes-${month}-${startedAt}` + (executionId ? `-${executionId}` : '');

  // Only one curation run may write at a time. Each run writes its Sync Log row first (no Status, no
  // Finished At) and then lists the rows of runs that are still open. Rows older than lockMinutes are
  // taken to be from a run that died without closing its row.
  const openRunsFormula = "AND({Automation} = '04 Subscription Boxes', {Finished At} = BLANK())";

  return {
    ok: !problems.length && !requestError,
    httpStatus: problems.length ? 500 : requestError ? 400 : 202,
    error: problems.length ? 'Settings problem. ' + problems.join('. ') + '.' : requestError,
    trigger, month, today, monthStart, shipDate, shelfLifeCutoff, repeatWindow, sellByBufferDays,
    lookbackMonths, monthFormula, openRunsFormula, lockMinutes: 60, startedAt, runId,
  };
}

const env = {
  AIRTABLE_TOKEN: $env.AIRTABLE_TOKEN,
  AIRTABLE_BASE_ID: $env.AIRTABLE_BASE_ID,
  SLACK_PACKING_WEBHOOK_URL: $env.SLACK_PACKING_WEBHOOK_URL,
  REPEAT_WINDOW: $env.REPEAT_WINDOW,
  SELL_BY_BUFFER_DAYS: $env.SELL_BY_BUFFER_DAYS,
};
return [{ json: readSettings('Schedule', env, null, new Date(), $execution.id) }];

