const env = {
  AIRTABLE_TOKEN: $env.AIRTABLE_TOKEN,
  AIRTABLE_BASE_ID: $env.AIRTABLE_BASE_ID,
  SLACK_PACKING_WEBHOOK_URL: $env.SLACK_PACKING_WEBHOOK_URL,
  REPEAT_WINDOW: $env.REPEAT_WINDOW,
  SELL_BY_BUFFER_DAYS: $env.SELL_BY_BUFFER_DAYS,
};
const req = $input.first().json;
const body = req.body && typeof req.body === 'object' && !Array.isArray(req.body) ? req.body : {};
const query = req.query && typeof req.query === 'object' ? req.query : {};
const asked = body.month != null && body.month !== '' ? body.month : query.month;
return [{ json: readSettings('Run Now', env, asked, new Date(), $execution.id) }];

// Only one curation run may write at a time: two runs planning the same month would reserve the
// same stock twice. Every run writes its own Sync Log row first, waits 2 seconds, then lists the rows of
// curation runs that are still open (no Finished At). It goes on only when no other open row was created
// before its own; on a tie, the lower Run ID goes on. A row with a Status, or older than lockMinutes,
// is from a run that is not running any more.
const ctx = $('Start: Curation Run').first().json;
const pages = $('Airtable: List Open Runs').all().map(i => i.json || {});
const rows = pages.flatMap(p => p.records || []);
const mine = rows.find(r => (r.fields || {})['Run ID'] === ctx.runId);
if (!mine || (pages.length && pages[pages.length - 1].offset)) {
  return [{ json: { clear: false, saved: 0, message: `The Sync Log row ${ctx.runId} could not be checked against other curation runs, so this run stopped before reading anything. Run again.` } }];
}
const key = r => [Date.parse(r.createdTime), String((r.fields || {})['Run ID'] || r.id)];
const earlier = (a, b) => a[0] < b[0] || (a[0] === b[0] && a[1] < b[1]);
const now = Date.now();
const blockers = rows.filter(r => r !== mine && !(r.fields || {})['Status']
  && now - Date.parse(r.createdTime) < ctx.lockMinutes * 60000 && earlier(key(r), key(mine)))
  .sort((a, b) => (earlier(key(a), key(b)) ? -1 : 1));
if (blockers.length) {
  const b = blockers[0];
  const started = String((b.fields || {})['Started At'] || b.createdTime).slice(0, 16).replace('T', ' ');
  return [{ json: { clear: false, saved: 0, message: `Another curation run (${b.fields['Run ID']}, started ${started} UTC) is still running, so this run stopped before reading anything. Its summary goes to Slack when it is done. If it is not running in n8n any more, set a Status on its Sync Log row, then run again.` } }];
}
return [{ json: { clear: true, openRuns: rows.length } }];

// A read failed after 3 tries. A rate limit (HTTP 429) is waited out (Airtable asks for 30 seconds)
// and the run starts again from its Sync Log row, at most twice per run. Anything else stops the run.
// Messages avoid ': ' (n8n keeps only the text after the last ': ' of a Code node error).
const steps = {
  'Airtable: Claim Run': 'Writing the Sync Log row for this run',
  'Airtable: List Open Runs': 'Reading Sync Log from Airtable',
  'Airtable: List Subscribers': 'Reading Subscribers from Airtable',
  'Airtable: List Products': 'Reading Products from Airtable',
  'Airtable: List Batches': 'Reading Production Batches from Airtable',
  'Airtable: List Box History': 'Reading Box History from Airtable',
  'Airtable: List Box Shipments': 'Reading Box Shipments from Airtable',
};
const err = $input.first().json.error || {};
const status = err.statusCode || err.status || (err.response && err.response.status) || 'unknown';
const found = JSON.stringify(err).match(/type\\*"\s*:\s*\\*"([A-Z][A-Z_]+)/);
const type = found ? ' ' + found[1] : '';
const step = steps[$prevNode.name] || 'An Airtable read';
const limited = Number(status) === 429;
const message = limited
  ? `${step} kept hitting the rate limit (HTTP 429${type}), also after waiting out the 30 second penalty twice. ` +
    "No box or stock was changed. Another app is using up this base's 5 requests a second, run again later."
  : `${step} failed with HTTP ${status}${type}. No box or stock was changed. ` +
    'Check AIRTABLE_TOKEN, AIRTABLE_BASE_ID and that the field names match base/schema.json, then run again.';
return [{ json: { retry: limited && $runIndex < 2, message, rateLimited: limited, saved: 0 } }];

// Subscription box planner. Pure functions: no n8n globals, so the same code runs in the
// "Code: Plan Boxes" node and in a plain Node.js harness.

const KNOWN_NEEDS = ['Nut-Free', 'Dairy-Free', 'Vegan', 'Gluten-Free'];

// Ingredient words that point to an allergen. They cross-check the allergen fields: when the
// ingredient list mentions an allergen that Contains Allergens and May Contain Traces do not list,
// the bar is treated as containing it and the product is reported for a person to fix.
const SCANS = {
  'Tree Nuts': {
    ignore: /\b(tree )?nut[- ]free\b/g,
    find: /\b(almonds?|hazelnuts?|walnuts?|pecans?|cashews?|pistachios?|macadamias?|brazil nuts?|pine nuts?|chestnuts?|praline|marzipan|nougat|gianduja|frangipane|tree nuts?|nuts?)\b/,
  },
  Peanuts: {
    ignore: /\bpeanut[- ]free\b/g,
    find: /\b(peanuts?|groundnuts?|arachis)\b/,
  },
  Milk: {
    // Plant milks are not dairy. A nut "cream" (hazelnut cream, a spread) often is, so only coconut cream is ignored.
    ignore: /\b(cocoa|shea|peanut|nut|almond|cashew|hazelnut|seed|sunflower) butter\b|\b(oat|soy|rice|almond|coconut|cashew|hazelnut) (milk|drink)\b|\bcoconut cream\b|\bcream of tartar\b|\b(milk|dairy|lactose)[- ]free\b/g,
    find: /\b(milk|cream|butter|buttermilk|whey|casein|caseinates?|lactose|yogh?urt|ghee|cheese|curds?|dairy)\b/,
  },
  Wheat: {
    ignore: /\b(gluten|wheat)[- ]free\b|\b(rice|almond|coconut|oat|corn|chickpea|tapioca|potato|buckwheat|cassava) flour\b|\bbuckwheat\b/g,
    find: /\b(wheat|gluten|barley|rye|spelt|malt|malted|semolina|farina|couscous|bulgur|flour|breadcrumbs?)\b/,
  },
};
// Animal ingredients for the Vegan check. Only the ingredient sentences count, not the
// "made on shared equipment" sentences, because a vegan bar may carry a milk trace warning.
const ANIMAL = /\b(milk|cream|butter|buttermilk|whey|casein|caseinates?|lactose|yogh?urt|ghee|cheese|curds?|dairy|eggs?|albumen|honey|gelatine?|beeswax|carmine|cochineal|shellac|lard|collagen)\b/;
const ADVISORY = /\b(may contain|shared equipment|same equipment|same line|facility|factory|traces?)\b/;
// Structured fields that also point to an allergen. A Hazelnut flavor note or a Milk chocolate type
// without the allergen listed is a data error, and the bar is treated as containing it. Ruby chocolate is
// made with milk powder, so it counts as milk too.
const NOTE_SIGNALS = { Hazelnut: 'Tree Nuts', Almond: 'Tree Nuts', Peanut: 'Peanuts' };
const TYPE_SIGNALS = { Milk: 'Milk', White: 'Milk', Ruby: 'Milk' };

function list(v) { return Array.isArray(v) ? v : []; }
function text(v) { return typeof v === 'string' ? v.trim() : ''; }
function num(v) { return typeof v === 'number' && Number.isFinite(v) ? v : 0; }
function addDays(isoDate, days) {
  const d = new Date(isoDate + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}
function plural(n, one, many) { return n === 1 ? one : many; }

// What a product contains: its allergen fields, plus anything the ingredients, the name, the flavor
// notes or the chocolate type point to (reported as a mismatch for a person to fix).
function describeProduct(rec) {
  const f = rec.fields || {};
  const contains = list(f['Contains Allergens']);
  const traces = list(f['May Contain Traces']);
  const labels = list(f['Diet Labels']);
  const ingredients = text(f['Ingredients']);
  const lower = ingredients.toLowerCase();
  const name = text(f['Name']);
  const type = text(f['Chocolate Type']);
  const notes = list(f['Flavor Notes']);
  const listed = new Set([...contains, ...traces]);
  const has = {};
  const mismatches = [];
  // The allergen fields are the source of truth; the ingredients, the name, the flavor notes and the
  // chocolate type can only add an allergen, never remove one.
  const sources = [['ingredients mention', lower], ['name mentions', name.toLowerCase()]];
  for (const [allergen, scan] of Object.entries(SCANS)) {
    let why = '';
    for (const [where, words] of sources) {
      const hit = words.replace(scan.ignore, ' ').match(scan.find);
      if (hit) { why = `the ${where} "${hit[0]}"`; break; }
    }
    const note = notes.find(n => NOTE_SIGNALS[n] === allergen);
    if (!why && note) why = `it has the flavor note ${note}`;
    if (!why && TYPE_SIGNALS[type] === allergen) why = `it is ${type} chocolate`;
    has[allergen] = listed.has(allergen) || Boolean(why);
    if (why && !listed.has(allergen)) mismatches.push(`${why} but ${allergen} is not listed`);
  }
  const ingredientPart = lower.split(/[.;]/).filter(s => !ADVISORY.test(s)).join('.')
    .replace(SCANS.Milk.ignore, ' ');
  const animal = ingredientPart.match(ANIMAL) || name.toLowerCase().replace(SCANS.Milk.ignore, ' ').match(ANIMAL);
  let vegan = labels.includes('Vegan') && !contains.includes('Milk') && !contains.includes('Eggs');
  if (vegan && animal) {
    vegan = false;
    mismatches.push(`it is labelled Vegan but the ${ingredientPart.match(ANIMAL) ? 'ingredients mention' : 'name mentions'} "${animal[0]}"`);
  } else if (vegan && (notes.includes('Honey') || TYPE_SIGNALS[type])) {
    vegan = false;
    mismatches.push(`it is labelled Vegan but ${notes.includes('Honey') ? 'it has the flavor note Honey' : `it is ${type} chocolate`}`);
  }
  return {
    id: rec.id,
    sku: text(f['SKU']),
    name,
    family: text(f['Flavor Family']) || 'Unknown',
    type: type || 'Unknown',
    notes,
    hasIngredients: ingredients.length > 0,
    has,
    vegan,
    mismatches,
    eligible: f['Status'] === 'Active' && f['Subscription Eligible'] === true && f['Category'] === 'Bar',
  };
}

// The first dietary need a product breaks, or null when it suits every need.
function brokenNeed(product, needs) {
  for (const need of needs) {
    if (need === 'Nut-Free' && (product.has['Tree Nuts'] || product.has.Peanuts)) return need;
    if (need === 'Dairy-Free' && product.has.Milk) return need;
    if (need === 'Gluten-Free' && product.has.Wheat) return need;
    if (need === 'Vegan' && !product.vegan) return need;
  }
  return null;
}

function planBoxes(input) {
  const ctx = input.ctx;
  const month = ctx.month;
  const warnings = [];
  const notPlanned = [];

  // Products: every bar is read, so a box planned earlier can be checked again even when its bar is no
  // longer an Active subscription bar (for example after a recall). Only Active, Subscription Eligible
  // bars go in new boxes. A bar without a SKU, or two records with the same SKU, cannot be told apart in
  // Box History, so they are left out and reported.
  const described = input.products.map(describeProduct);
  const describedById = new Map(described.map(p => [p.id, p]));
  const rawById = new Map(input.products.map(r => [r.id, r.fields || {}]));
  const candidates = described.filter(p => p.eligible);
  const perSku = new Map();
  for (const p of candidates) perSku.set(p.sku, (perSku.get(p.sku) || 0) + 1);
  for (const [sku, n] of [...perSku].sort()) {
    if (!sku) warnings.push(`${n} subscription ${plural(n, 'bar has', 'bars have')} no SKU, so ${plural(n, 'it does', 'they do')} not go in a box until the SKU is filled in.`);
    else if (n > 1) warnings.push(`${sku}: ${n} product records have this SKU, so none of them goes in a box until the duplicate is removed.`);
  }
  const products = candidates.filter(p => p.sku && perSku.get(p.sku) === 1)
    .sort((a, b) => (a.sku < b.sku ? -1 : 1));
  const productById = new Map(products.map(p => [p.id, p]));
  for (const p of products) {
    for (const m of p.mismatches) warnings.push(`${p.sku}: ${m}. It is kept out of boxes for that need until the record is fixed.`);
    if (!p.hasIngredients) warnings.push(`${p.sku}: no ingredient list, so it only goes to subscribers without dietary needs.`);
  }

  // Stock: Released batches made on or before today with best before after the cutoff.
  const batchesByProduct = new Map();
  const batchById = new Map();
  for (const rec of input.batches) {
    const f = rec.fields || {};
    const links = list(f['Product']);
    if (f['Status'] !== 'Released' || links.length !== 1 || !productById.has(links[0])) continue;
    const producedOn = text(f['Produced On']);
    const bestBefore = text(f['Best Before']);
    if (!producedOn || producedOn > ctx.today || !bestBefore || bestBefore <= ctx.shelfLifeCutoff) continue;
    const reserved = num(f['Quantity Reserved']);
    const available = Math.max(num(f['Quantity Made']) - reserved - num(f['Quantity Sold']), 0);
    if (available <= 0) continue;
    const b = { id: rec.id, code: text(f['Batch Code']) || rec.id, productId: links[0], bestBefore, reserved,
                reservedNow: reserved, left: available };
    batchById.set(b.id, b);
    if (!batchesByProduct.has(b.productId)) batchesByProduct.set(b.productId, []);
    batchesByProduct.get(b.productId).push(b);
  }
  for (const arr of batchesByProduct.values()) {
    arr.sort((a, b) => (a.bestBefore !== b.bestBefore ? (a.bestBefore < b.bestBefore ? -1 : 1) : (a.code < b.code ? -1 : 1)));
  }
  const remaining = new Map(products.map(p => [p.id, (batchesByProduct.get(p.id) || []).reduce((s, b) => s + b.left, 0)]));
  const initialStock = new Map(remaining);

  // Subscribers: Active only, longest tenure first (Started On, then Subscriber ID).
  const subs = [];
  const seenIds = new Set();
  const active = input.subscribers.filter(r => (r.fields || {})['Status'] === 'Active').map(r => {
    const f = r.fields;
    return { id: r.id, subId: text(f['Subscriber ID']), name: text(f['Name']) || '(no name)', plan: text(f['Plan']),
             startedOn: text(f['Started On']), needs: list(f['Dietary Needs']), dislikes: list(f['Flavor Dislikes']) };
  }).sort((a, b) => {
    const sa = a.startedOn || '9999-12-31';
    const sb = b.startedOn || '9999-12-31';
    if (sa !== sb) return sa < sb ? -1 : 1;
    return a.subId < b.subId ? -1 : a.subId > b.subId ? 1 : (a.id < b.id ? -1 : 1);
  });
  for (const s of active) {
    const size = /^(\d+) Bars?$/.exec(s.plan);
    const unknown = s.needs.filter(n => !KNOWN_NEEDS.includes(n));
    if (!s.subId) notPlanned.push({ subscriberId: '(none)', recordId: s.id, name: s.name, reason: 'the record has no Subscriber ID' });
    else if (seenIds.has(s.subId)) notPlanned.push({ subscriberId: s.subId, recordId: s.id, name: s.name, reason: 'another Active record has the same Subscriber ID' });
    else if (!size || Number(size[1]) < 1) notPlanned.push({ subscriberId: s.subId, recordId: s.id, name: s.name, reason: s.plan ? `the plan "${s.plan}" is not a number of bars` : 'no plan is set' });
    // One box is written with at most 10 records per request (Airtable's limit), one per bar.
    else if (Number(size[1]) > 10) notPlanned.push({ subscriberId: s.subId, recordId: s.id, name: s.name, reason: `the plan "${s.plan}" has more than 10 bars, which this workflow does not plan` });
    else if (unknown.length) notPlanned.push({ subscriberId: s.subId, recordId: s.id, name: s.name, reason: `the dietary need ${unknown.map(n => '"' + n + '"').join(', ')} has no safety rule yet, so a person must pick these bars` });
    else {
      s.planSize = Number(size[1]);
      s.shipmentId = `BOX-${month}-${s.subId}`;
      subs.push(s);
    }
    if (s.subId) seenIds.add(s.subId);
  }

  // Earlier boxes: Box History rows plus the Products of earlier Box Shipments (not Cancelled).
  const monthsBySub = new Map();
  const add = (subRec, m, productId) => {
    if (!monthsBySub.has(subRec)) monthsBySub.set(subRec, new Map());
    const byMonth = monthsBySub.get(subRec);
    if (!byMonth.has(m)) byMonth.set(m, new Set());
    if (productId) byMonth.get(m).add(productId);
  };
  // The bars of a cancelled box never reached the subscriber, so its Box History rows do not count.
  const cancelledBoxes = new Set(input.shipments.filter(r => (r.fields || {})['Status'] === 'Cancelled').map(r => r.id));
  const historyIds = new Set();
  // Box History rows for this month, per subscriber: bars recorded by a person or by an older process.
  const recordedThisMonth = new Map();
  for (const rec of input.history) {
    const f = rec.fields || {};
    const m = text(f['Box Month']);
    if (text(f['History ID'])) historyIds.add(text(f['History ID']));
    if (list(f['Box Shipment']).some(id => cancelledBoxes.has(id))) continue;
    if (m === month) {
      for (const subRec of list(f['Subscriber'])) {
        if (!recordedThisMonth.has(subRec)) recordedThisMonth.set(subRec, { rows: 0, products: [] });
        const r = recordedThisMonth.get(subRec);
        r.rows += 1;
        r.products.push(...list(f['Product']));
      }
      continue;
    }
    if (!/^\d{4}-\d{2}$/.test(m) || m > month) continue;
    for (const subRec of list(f['Subscriber'])) for (const pid of list(f['Product'])) add(subRec, m, pid);
  }
  const existingBoxes = new Map();
  for (const rec of input.shipments) {
    const f = rec.fields || {};
    const m = text(f['Box Month']);
    if (m === month) {
      existingBoxes.set(text(f['Shipment ID']), rec);
      for (const subRec of list(f['Subscriber'])) existingBoxes.set('sub:' + subRec, rec);
      continue;
    }
    if (!/^\d{4}-\d{2}$/.test(m) || m > month || f['Status'] === 'Cancelled') continue;
    for (const subRec of list(f['Subscriber'])) for (const pid of list(f['Products'])) add(subRec, m, pid);
  }
  const lastBoxProducts = s => {
    const byMonth = monthsBySub.get(s.id);
    if (!byMonth || ctx.repeatWindow < 1) return { months: [], ids: new Set() };
    const months = [...byMonth.keys()].sort().reverse().slice(0, ctx.repeatWindow);
    const ids = new Set();
    for (const m of months) for (const pid of byMonth.get(m)) ids.add(pid);
    return { months, ids };
  };

  // Split subscribers into those that already have a box this month and those that need one.
  const alreadyPlanned = [];
  const recordedOnly = [];
  const repairs = [];
  const toPlan = [];
  // A box planned (or recorded) before this run is never changed, but its bars are checked again against the
  // subscriber's needs today: product data or the needs may have changed since. Every bar that no longer suits
  // is reported so a person takes it out before packing.
  const conflicts = [];
  const recheck = (s, where, productIds, advice) => {
    for (const pid of [...new Set(productIds)]) {
      const p = describedById.get(pid);
      if (!p) {
        if (s.needs.length) conflicts.push(`${where} has a product that is no longer a bar in Products (record ${pid}), so it cannot be checked against ${s.needs.join(', ')}. ${advice}`);
        continue;
      }
      const need = brokenNeed(p, s.needs);
      if (need) conflicts.push(`${where} has ${p.sku || pid}, which does not suit ${need}. ${advice}`);
      else if (s.needs.length && !p.hasIngredients) conflicts.push(`${where} has ${p.sku || pid}, which has no ingredient list to check against ${s.needs.join(', ')}. ${advice}`);
    }
  };
  for (const s of subs) {
    const existing = existingBoxes.get(s.shipmentId) || existingBoxes.get('sub:' + s.id);
    if (!existing) {
      // Bars for this month already in Box History without a Box Shipment: a box was recorded outside this
      // workflow (this workflow saves the box before its history rows). Never plan a second box on top.
      const recorded = recordedThisMonth.get(s.id);
      if (recorded) {
        recordedOnly.push({ subscriberId: s.subId, name: s.name, bars: recorded.rows });
        recheck(s, `${s.subId} ${s.name} (${month} bars in Box History)`, recorded.products,
          'If it has not shipped, take it out by hand; if it has, tell the subscriber.');
      } else {
        toPlan.push(s);
      }
      continue;
    }
    const f = existing.fields || {};
    alreadyPlanned.push({ shipmentId: text(f['Shipment ID']) || s.shipmentId, subscriberId: s.subId, name: s.name,
                          fill: text(f['Fill Status']), status: text(f['Status']), reason: text(f['Shortfall Reason']),
                          planned: num(f['Bars Planned']), packed: num(f['Bars Packed']) });
    if (f['Status'] === 'Cancelled') continue;
    recheck(s, `${text(f['Shipment ID']) || s.shipmentId} for ${s.subId} ${s.name}`, list(f['Products']),
      f['Status'] === 'Shipped' ? 'The box is marked Shipped, so tell the subscriber.' : 'Take it out by hand before packing.');
    // Box History rows a failed run did not write yet (the next run adds them).
    const missing = [];
    for (const pid of list(f['Products'])) {
      const p = productById.get(pid);
      if (!p) continue;
      const hid = `${month} / ${s.subId} / ${p.sku}`;
      if (!historyIds.has(hid)) missing.push({ 'History ID': hid, 'Subscriber': [s.id], 'Product': [pid], 'Box Month': month });
    }
    if (missing.length) repairs.push({ shipmentId: text(f['Shipment ID']) || s.shipmentId, subscriberId: s.subId, boxRecordId: existing.id, history: missing });
  }

  // Which bars each subscriber could take, ignoring stock: diet, dislikes and the repeat window.
  const verdict = (s, p, window) => {
    if (brokenNeed(p, s.needs)) return 'diet';
    if (s.needs.length && !p.hasIngredients) return 'unverified';
    if (p.notes.some(n => s.dislikes.includes(n))) return 'dislike';
    if (window.ids.has(p.id)) return 'repeat';
    return 'ok';
  };
  for (const s of toPlan) {
    s.window = lastBoxProducts(s);
    s.verdicts = new Map(products.map(p => [p.id, verdict(s, p, s.window)]));
    s.need = products.filter(p => s.verdicts.get(p.id) === 'ok' && initialStock.get(p.id) > 0).map(p => p.id);
    s.tight = s.need.length <= s.planSize;
  }

  // Allocate in tenure order, reserving stock as we go.
  const boxes = [];
  const writes = [];
  const usedBatches = new Map();
  toPlan.forEach((s, index) => {
    const later = toPlan.slice(index + 1).filter(t => t.tight);
    const demand = pid => later.filter(t => t.need.includes(pid)).length;
    let pool = products.filter(p => s.verdicts.get(p.id) === 'ok' && remaining.get(p.id) > 0);
    const picked = [];
    const families = new Map();
    const types = new Map();
    while (picked.length < s.planSize && pool.length) {
      // Rank: 1. leave alone a bar that a later subscriber with no alternatives needs, when stock is
      // too short for both; 2. the flavor family with the fewest bars in the box so far; 3. the same
      // for chocolate type; 4. the most spare stock; 5. SKU, so every run gives the same answer.
      const scored = pool.map(p => {
        const d = demand(p.id);
        const left = remaining.get(p.id);
        return { p, key: [left <= d ? 1 : 0, families.get(p.family) || 0, types.get(p.type) || 0, -(left - d)] };
      });
      scored.sort((a, b) => {
        for (let i = 0; i < a.key.length; i++) if (a.key[i] !== b.key[i]) return a.key[i] - b.key[i];
        return a.p.sku < b.p.sku ? -1 : 1;
      });
      const best = scored[0].p;
      picked.push(best);
      families.set(best.family, (families.get(best.family) || 0) + 1);
      types.set(best.type, (types.get(best.type) || 0) + 1);
      remaining.set(best.id, remaining.get(best.id) - 1);
      pool = pool.filter(p => p.id !== best.id);
    }

    // One unit per bar from the batch with the earliest best before date.
    const bars = picked.sort((a, b) => (a.sku < b.sku ? -1 : 1)).map(p => {
      const batch = batchesByProduct.get(p.id).find(b => b.left > 0);
      batch.left -= 1;
      return { product: p, batch };
    });
    const reserve = [];
    const release = [];
    const touched = new Map();
    for (const { batch } of bars) touched.set(batch.id, (touched.get(batch.id) || 0) + 1);
    for (const [bid, units] of touched) {
      const b = batchById.get(bid);
      release.push({ id: bid, fields: { 'Quantity Reserved': b.reservedNow } });
      b.reservedNow += units;
      reserve.push({ id: bid, fields: { 'Quantity Reserved': b.reservedNow } });
      usedBatches.set(bid, b);
    }

    const packed = bars.length;
    const fill = packed === s.planSize ? 'Full' : packed === 0 ? 'Empty' : 'Partial';
    const reason = fill === 'Full' ? '' : shortfallReason(s, products, bars, initialStock, remaining, ctx);
    const header = `Box ${month} for ${s.name} (${s.subId}), ${s.plan} plan.`;
    const needsLine = `Dietary needs: ${s.needs.length ? s.needs.join(', ') : 'none'}. Dislikes: ${s.dislikes.length ? s.dislikes.join(', ') : 'none'}.`;
    const lines = bars.map(({ product, batch }, i) => `${i + 1}. ${product.sku}, ${product.name}, batch ${batch.code} (best before ${batch.bestBefore})`);
    const packingList = [header, needsLine, ...(lines.length ? lines : ['No bars could be planned.']),
      ...(fill === 'Full' ? [] : [`Short: ${reason}`]),
      s.needs.length ? 'Every bar was checked against Contains Allergens, May Contain Traces, its ingredients, name, flavor notes and chocolate type.' : ''].filter(Boolean).join('\n');
    const fields = {
      'Shipment ID': s.shipmentId,
      'Subscriber': [s.id],
      'Box Month': month,
      'Packing List': packingList,
      'Bars Planned': s.planSize,
      'Bars Packed': packed,
      'Fill Status': fill,
      'Status': 'Planned',
    };
    if (packed) {
      fields['Products'] = bars.map(b => b.product.id);
      fields['Batches'] = [...touched.keys()];
    }
    if (reason) fields['Shortfall Reason'] = reason;
    const batchCodes = [...touched.keys()].map(id => batchById.get(id).code);
    boxes.push({ shipmentId: s.shipmentId, subscriberId: s.subId, name: s.name, needs: s.needs, planned: s.planSize, packed, fill, reason,
                 skus: bars.map(b => b.product.sku), batches: batchCodes });
    writes.push({
      kind: 'new', shipmentId: s.shipmentId, subscriberId: s.subId, reserve, release, releaseNote: batchCodes.join(', '),
      box: fields, boxRecordId: null,
      history: bars.map(b => ({ 'History ID': `${month} / ${s.subId} / ${b.product.sku}`, 'Subscriber': [s.id], 'Product': [b.product.id], 'Box Month': month })),
    });
  });
  for (const r of repairs) writes.push({ kind: 'repair', shipmentId: r.shipmentId, subscriberId: r.subscriberId, reserve: [], release: [], releaseNote: '', box: null, boxRecordId: r.boxRecordId, history: r.history });

  verifyPlan(boxes, writes, products, toPlan, batchById, rawById);

  const soldOut = products.filter(p => initialStock.get(p.id) > 0 && remaining.get(p.id) === 0).map(p => p.sku);
  return {
    month, runId: ctx.runId, trigger: ctx.trigger, startedAt: ctx.startedAt, today: ctx.today,
    shipDate: ctx.shipDate, shelfLifeCutoff: ctx.shelfLifeCutoff, repeatWindow: ctx.repeatWindow,
    activeSubscribers: active.length, eligibleBars: products.length,
    boxes, alreadyPlanned, recordedOnly, notPlanned, warnings, soldOut, conflicts,
    repairRows: repairs.reduce((n, r) => n + r.history.length, 0),
    barsReserved: boxes.reduce((n, b) => n + b.packed, 0),
    batchesUsed: usedBatches.size,
    stockLeft: Object.fromEntries(products.map(p => [p.sku, remaining.get(p.id)])),
    writes,
  };
}

// Why a box is short, counting every subscription bar that was not packed by its first reason.
function shortfallReason(s, products, bars, initialStock, remaining, ctx) {
  const packedIds = new Set(bars.map(b => b.product.id));
  const groups = { unverified: [], diet: [], dislike: [], repeat: [], none: [], used: [] };
  for (const p of products) {
    if (packedIds.has(p.id)) continue;
    const v = s.verdicts.get(p.id);
    if (v !== 'ok') groups[v].push(p.sku);
    else if (initialStock.get(p.id) > 0) groups.used.push(p.sku);
    else groups.none.push(p.sku);
  }
  const skus = a => ` (${a.join(', ')})`;
  const parts = [];
  if (groups.diet.length) parts.push(`${groups.diet.length} not suitable for ${s.needs.join(' and ')}`);
  if (groups.unverified.length) parts.push(`${groups.unverified.length} with no ingredient list to check${skus(groups.unverified)}`);
  if (groups.dislike.length) parts.push(`${groups.dislike.length} with a disliked flavor (${s.dislikes.join(', ')})`);
  if (groups.repeat.length) parts.push(`${groups.repeat.length} in the last ${ctx.repeatWindow === 1 ? 'box' : ctx.repeatWindow + ' boxes'}${skus(groups.repeat)}`);
  if (groups.none.length) parts.push(`${groups.none.length} out of stock${skus(groups.none)}`);
  if (groups.used.length) parts.push(`${groups.used.length} used up by longer-standing subscribers${skus(groups.used)}`);
  const others = products.length - bars.length;
  return `${bars.length} of ${s.planSize} bars packed. The other ${others} subscription ${plural(others, 'bar', 'bars')}: ${parts.join('; ')}.`;
}

// A last check before anything is written. It recomputes the rules from the raw plan, so a bug in
// the allocation above stops the run instead of reaching a subscriber. The allergen part reads the
// product's own Airtable fields again, so it does not depend on describeProduct either.
const LISTED_BREAKS = { 'Nut-Free': ['Tree Nuts', 'Peanuts'], 'Dairy-Free': ['Milk'], 'Gluten-Free': ['Wheat'], 'Vegan': ['Milk', 'Eggs'] };
function verifyPlan(boxes, writes, products, toPlan, batchById, rawById) {
  const bySku = new Map(products.map(p => [p.sku, p]));
  const subs = new Map(toPlan.map(s => [s.subId, s]));
  for (const box of boxes) {
    const s = subs.get(box.subscriberId);
    if (new Set(box.skus).size !== box.skus.length) throw new Error(`Safety check failed, ${box.shipmentId} has the same bar twice`);
    if (box.skus.length > s.planSize) throw new Error(`Safety check failed, ${box.shipmentId} has more bars than the plan`);
    for (const sku of box.skus) {
      const p = bySku.get(sku);
      if (brokenNeed(p, s.needs) || (s.needs.length && !p.hasIngredients)) throw new Error(`Safety check failed, ${sku} does not suit ${s.subId} (${s.needs.join(', ')})`);
      if (s.window.ids.has(p.id)) throw new Error(`Safety check failed, ${sku} was in a recent box of ${s.subId}`);
      const raw = rawById.get(p.id) || {};
      const contains = list(raw['Contains Allergens']);
      const listed = new Set([...contains, ...list(raw['May Contain Traces'])]);
      for (const need of s.needs) {
        const breaks = need === 'Vegan' ? LISTED_BREAKS.Vegan.filter(a => contains.includes(a)) : (LISTED_BREAKS[need] || []).filter(a => listed.has(a));
        if (breaks.length || (need === 'Vegan' && !list(raw['Diet Labels']).includes('Vegan')) || !text(raw['Ingredients'])) {
          throw new Error(`Safety check failed, ${sku} does not suit ${s.subId} (${need})`);
        }
      }
    }
  }
  for (const b of batchById.values()) {
    if (b.left < 0) throw new Error(`Safety check failed, batch ${b.code} would be over-reserved`);
  }
  for (const w of writes) {
    if (w.reserve.length > 10 || w.history.length > 10) throw new Error(`Safety check failed, ${w.shipmentId} needs more than 10 records in one write`);
  }
}

// ---- n8n glue: every read node gives one item per page. A problem never throws here: the run goes to
// the failure path, which closes its Sync Log row and raises the alert.
let plan;
try {
  const ctx = $('Start: Curation Run').first().json;
  // A read that stopped at the page limit would hide records (an earlier box, a batch), so it stops the run.
  const records = name => {
    const pages = $(name).all().map(i => i.json || {});
    if (pages.length && pages[pages.length - 1].offset) {
      throw new Error(`${name.replace('Airtable: List ', '')} has more records than one run reads. Raise maxRequests on its read node, then run again.`);
    }
    return pages.flatMap(p => p.records || []);
  };
  plan = planBoxes({
    ctx,
    subscribers: records('Airtable: List Subscribers'),
    products: records('Airtable: List Products'),
    batches: records('Airtable: List Batches'),
    history: records('Airtable: List Box History'),
    shipments: records('Airtable: List Box Shipments'),
  });
} catch (e) {
  return [{ json: { failed: true, saved: 0, message: `The plan was not made, no box or stock was changed. ${String((e && e.message) || e)}` } }];
}
return [{ json: Object.assign({ failed: false }, plan) }];

// One item per box, so each pass writes one box and a retry can never repeat another box's writes.
const writes = $input.first().json.writes;
return writes.map((w, i) => ({ json: Object.assign({}, w, { position: i + 1, total: writes.length }), pairedItem: { item: 0 } }));

// The stock for one box could not be reserved. The answer may have been lost after
// Airtable saved it, so the batches are set back to their numbers from the start of the run. Explain what is saved and what to do, without ': ' (n8n keeps only the text after
// the last ': ' of a Code node error).
const statusOf = err => (err && (err.statusCode || err.status || (err.response && err.response.status))) || 'unknown';
const reasonOf = err => {
  if (!err) return 'no answer';
  const status = statusOf(err);
  const found = JSON.stringify(err).match(/type\\*"\s*:\s*\\*"([A-Z][A-Z_]+)/);
  // n8n drops the response body of a 429 when there is no pagination, so say what the status means
  return `HTTP ${status}${found ? ' ' + found[1] : Number(status) === 429 ? ' rate limit' : ''}`;
};
const limitedBy = err => Number(statusOf(err)) === 429;
const box = $('Loop: Boxes').item.json;
const month = $('Start: Curation Run').first().json.month;
const before = box.position - 1;
const newSaved = $('Code: Plan Boxes').first().json.writes.slice(0, before).filter(w => w.kind === 'new').length;
const done = `${before} ${before === 1 ? 'box' : 'boxes'} before it ${before === 1 ? 'is' : 'are'} saved.`;
const again = `Run again for ${month} to carry on, saved boxes are skipped.`;
return { json: Object.assign({}, box, { stage: 'reserve', reason: reasonOf($json.error), rateLimited: limitedBy($json.error) }) };

// Keep the box record id for the Box History links. Airtable always answers an upsert with the record;
