    `(${reasonOf(item.error)}), so its stock stays reserved. If ${item.shipmentId} is not in Box Shipments, ${fixNote.charAt(0).toLowerCase() + fixNote.slice(1)}. Then run again. ${done}`;
} else if (undone) {
  message = `${item.shipmentId} could not be saved (${item.reason}). Its stock reservation was undone. ${done} ${again}`;
} else {
  message = `${item.shipmentId} could not be saved (${item.reason}) and its stock reservation could not be undone ` +
    `(${reasonOf(item.error)}). ${fixNote}, then run again. ${done}`;
}
return { json: { message, saved: newSaved, rateLimited: !undone && Boolean(item.error) && limitedBy(item.error) } };

// The run stops. Its Sync Log row is closed as Failed first, so the next run is not held back by it.
const ctx = $('Start: Curation Run').first().json;
const f = $input.first().json;
let checked = 0;
try { checked = $('Code: Plan Boxes').first().json.activeSubscribers || 0; } catch (e) { checked = 0; }
let claimed = false;
try { claimed = $('Airtable: Claim Run').all().some(i => Array.isArray((i.json || {}).records)); } catch (e) { claimed = false; }
const fields = {
  'Run ID': ctx.runId,
  'Automation': '04 Subscription Boxes',
  'Trigger': ctx.trigger,
  'Started At': ctx.startedAt,
  'Finished At': new Date().toISOString(),
  'Status': 'Failed',
  'Items Checked': checked,
  'Items Changed': f.saved || 0,
  'Errors': 1,
  'Details': f.message,
};
const closeNote = claimed
  ? ` The Sync Log row ${ctx.runId} could not be closed either, so new curation runs wait for it for up to ${ctx.lockMinutes} minutes. Set its Status by hand to run sooner.`
  : ' The Sync Log row for this run could not be written either.';
return [{ json: { fields, message: f.message, closeNote, rateLimited: Boolean(f.rateLimited) } }];

// The Slack summary and the Sync Log text, from the plan (every write succeeded to get here).
const plan = $('Code: Plan Boxes').first().json;
const count = fill => plan.boxes.filter(b => b.fill === fill).length;
const full = count('Full');
const partial = count('Partial');
const empty = count('Empty');
const short = plan.boxes.filter(b => b.fill !== 'Full');
// Boxes planned by an earlier run of this month that are not full are listed again: that run may have
// stopped before its summary went out.
const shortBefore = plan.alreadyPlanned.filter(b => b.fill && b.fill !== 'Full' && b.status !== 'Cancelled');
const notFullBefore = shortBefore.length;
const n = (k, one, many) => `${k} ${k === 1 ? one : many}`;
const lines = [`*Subscription boxes for ${plan.month}* (${plan.trigger}, run ${plan.runId})`];
lines.push(`${n(plan.activeSubscribers, 'active subscriber', 'active subscribers')}. ` +
  (plan.boxes.length
    ? `Planned this run: ${n(plan.boxes.length, 'box', 'boxes')} (${full} full, ${partial} partial, ${empty} empty), ` +
      `${n(plan.barsReserved, 'bar', 'bars')} reserved from ${n(plan.batchesUsed, 'batch', 'batches')}.`
    : 'Nothing new to plan this run, no stock was reserved.') +
  ` Planned before: ${n(plan.alreadyPlanned.length, 'box', 'boxes')}` +
  (notFullBefore ? ` (${notFullBefore} not full).` : '.'));
// Every subscriber is listed; only a message that would pass Slack's 40,000 characters is cut short.
let room = 35000;
const section = (title, items) => {
  if (!items.length) return;
  lines.push('', `*${title} (${items.length})*`);
  let shown = 0;
  for (const t of items) {
    if (t.length + 3 > room) break;
    lines.push(`• ${t}`);
    room -= t.length + 3;
    shown += 1;
  }
  if (shown < items.length) lines.push(`• and ${items.length - shown} more, see Box Shipments and Subscribers in Airtable`);
};
// Allergen safety first: a box planned before whose bar no longer suits the subscriber's needs today.
section('Bars to take out before packing', plan.conflicts);
if (plan.conflicts.length) lines.push('This run did not change these boxes. A bar taken out still holds its Quantity Reserved, so lower it by 1 on that batch.');
section('Not fully filled', short.map(b => `${b.subscriberId} ${b.name}, ${b.reason}`).concat(
  shortBefore.map(b => `${b.subscriberId} ${b.name}, ${b.reason || `${b.packed} of ${b.planned} bars packed`} (planned by an earlier run)`)));
section('Not planned, the subscriber record needs a person', plan.notPlanned.map(p => `${p.subscriberId} ${p.name}, ${p.reason}.`));
section(`Bars for ${plan.month} already in Box History without a Box Shipment, so no new box`,
  plan.recordedOnly.map(r => `${r.subscriberId} ${r.name} (${n(r.bars, 'bar', 'bars')})`));
if (plan.recordedOnly.length) {
  lines.push(`These boxes were recorded outside this workflow. To plan one here instead, delete that subscriber's Box History rows for ${plan.month} and run again.`);
}
section('Product data to check', plan.warnings);
if (plan.soldOut.length) lines.push('', `*Used up by this run:* ${plan.soldOut.join(', ')}`);
if (plan.repairRows) lines.push('', `Added ${n(plan.repairRows, 'missing Box History row', 'missing Box History rows')} for boxes planned before.`);
const text = lines.join('\n');
const clean = !short.length && !shortBefore.length && !plan.notPlanned.length && !plan.warnings.length
  && !plan.recordedOnly.length && !plan.conflicts.length;
return [{ json: { text, status: clean ? 'Success' : 'Partial' } }];

// The run's Sync Log row gets its counts and a Finished At, which also lets the next run start.
// Slack's answer (or error) is the input.
const plan = $('Code: Plan Boxes').first().json;
const summary = $('Code: Build Summary').first().json;
const slackError = $input.first().json.error;
const fields = {
  'Run ID': plan.runId,
  'Automation': '04 Subscription Boxes',
  'Trigger': plan.trigger,
  'Started At': plan.startedAt,
  'Finished At': new Date().toISOString(),
  // the boxes are saved but the packing team was not told, so the run is not a full success
  'Status': slackError ? 'Partial' : summary.status,
  'Items Checked': plan.activeSubscribers,
  'Items Changed': plan.boxes.length,
  'Errors': slackError ? 1 : 0,
  'Details': summary.text.replace(/\*/g, '') + (slackError ? '\n\nThe Slack summary could not be posted.' : ''),
};
const status = slackError ? (slackError.statusCode || slackError.status || 'unknown') : null;
return [{ json: { fields, slackFailed: Boolean(slackError), slackStatus: status } }];
